{"tool":"write","path":"reports/export.py","content":""""CSV export helpers."""

def _quote(field):
    if any(char in field for char in (',', '"', '\r', '\n')):
        return '"' + field.replace('"', '""') + '"'
    return field


def _text(value):
    if value is None:
        return ''
    return str(value)


def export_csv(rows, columns):
    selected = []
    seen = set()
    for column in columns:
        if not isinstance(column, str):
            raise ValueError('column names must be strings')
        if column in seen:
            raise ValueError('duplicate column name: %r' % (column,))
        seen.add(column)
        selected.append(column)

    chunks = [','.join(_quote(column) for column in selected), '\r\n']
    for row in rows:
        chunks.append(','.join(_quote(_text(row.get(column))) for column in selected))
        chunks.append('\r\n')
    return ''.join(chunks)
